/*! Compact QR encoder for the hub's security dialog: byte mode, error level M, versions 1-10 (up to 213 bytes),
 *  best-of-8 masks, rendered as an SVG string. Self-contained, no dependencies. MIT licence.
 *  qrcode.encode(text) -> { version, size, get(r, c) }   qrcode.svg(text, { size, margin, dark, light }) -> '<svg ...>' */
(function (root) {
  'use strict';
  // Level M block structure per version: [ecCodewordsPerBlock, [[blocks, dataCodewordsPerBlock], ...]]
  const EC_M = [null,
    [10, [[1, 16]]], [16, [[1, 28]]], [26, [[1, 44]]], [18, [[2, 32]]], [24, [[2, 43]]],
    [16, [[4, 27]]], [18, [[4, 31]]], [22, [[2, 38], [2, 39]]], [22, [[3, 36], [2, 37]]], [26, [[4, 43], [1, 44]]]];
  const ALIGN = [null, [], [6, 18], [6, 22], [6, 26], [6, 30], [6, 34], [6, 22, 38], [6, 24, 42], [6, 26, 46], [6, 28, 50]];
  const MASKS = [
    (r, c) => (r + c) % 2 === 0,
    (r) => r % 2 === 0,
    (r, c) => c % 3 === 0,
    (r, c) => (r + c) % 3 === 0,
    (r, c) => (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0,
    (r, c) => ((r * c) % 2 + (r * c) % 3) === 0,
    (r, c) => (((r * c) % 2 + (r * c) % 3) % 2) === 0,
    (r, c) => (((r + c) % 2 + (r * c) % 3) % 2) === 0,
  ];

  // GF(256) with the QR primitive polynomial 0x11d
  const EXP = new Uint8Array(512), LOG = new Uint8Array(256);
  for (let i = 0, x = 1; i < 255; i++) { EXP[i] = x; LOG[x] = i; x <<= 1; if (x & 256) x ^= 0x11d; }
  for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];
  const mul = (a, b) => (a && b) ? EXP[LOG[a] + LOG[b]] : 0;
  function rsGenerator(n) {
    let g = [1];
    for (let i = 0; i < n; i++) {
      const ng = new Array(g.length + 1).fill(0);
      for (let j = 0; j < g.length; j++) { ng[j] ^= g[j]; ng[j + 1] ^= mul(g[j], EXP[i]); }
      g = ng;
    }
    return g;
  }
  function rsEncode(data, n) {
    const g = rsGenerator(n), res = new Array(n).fill(0);
    for (const d of data) {
      const f = d ^ res.shift(); res.push(0);
      if (f) for (let j = 0; j < n; j++) res[j] ^= mul(g[j + 1], f);
    }
    return res;
  }

  function toBytes(text) {
    if (typeof TextEncoder !== 'undefined') return Array.from(new TextEncoder().encode(String(text)));
    return Array.from(Buffer.from(String(text), 'utf8'));
  }
  function dataCapacity(v) { return EC_M[v][1].reduce((s, g) => s + g[0] * g[1], 0); }
  function chooseVersion(len) {
    for (let v = 1; v <= 10; v++) if (4 + (v < 10 ? 8 : 16) + 8 * len <= dataCapacity(v) * 8) return v;
    throw new Error('QR: text too long (max 213 bytes)');
  }
  function codewords(data, v) {
    const [ec, groups] = EC_M[v];
    const cap = dataCapacity(v) * 8;
    const bits = [];
    const put = (val, n) => { for (let i = n - 1; i >= 0; i--) bits.push((val >>> i) & 1); };
    put(4, 4); put(data.length, v < 10 ? 8 : 16);
    for (const d of data) put(d, 8);
    put(0, Math.min(4, cap - bits.length));
    while (bits.length % 8) bits.push(0);
    for (let i = 0; bits.length < cap; i++) put(i & 1 ? 0x11 : 0xec, 8);
    const all = [];
    for (let i = 0; i < bits.length; i += 8) { let x = 0; for (let j = 0; j < 8; j++) x = (x << 1) | bits[i + j]; all.push(x); }
    const blocks = []; let p = 0;
    for (const [n, c] of groups) for (let i = 0; i < n; i++) { blocks.push(all.slice(p, p + c)); p += c; }
    const ecs = blocks.map(b => rsEncode(b, ec));
    const out = [];
    const longest = Math.max(...blocks.map(b => b.length));
    for (let i = 0; i < longest; i++) for (const b of blocks) if (i < b.length) out.push(b[i]);
    for (let i = 0; i < ec; i++) for (const e of ecs) out.push(e[i]);
    return out;
  }

  function skeleton(v) {
    const N = 17 + 4 * v;
    const m = Array.from({ length: N }, () => new Uint8Array(N));
    const fn = Array.from({ length: N }, () => new Uint8Array(N));
    const set = (r, c, val) => { if (r >= 0 && c >= 0 && r < N && c < N) { m[r][c] = val ? 1 : 0; fn[r][c] = 1; } };
    const finder = (r0, c0) => {
      for (let r = -1; r <= 7; r++) for (let c = -1; c <= 7; c++) {
        const inner = r >= 0 && r <= 6 && c >= 0 && c <= 6;
        set(r0 + r, c0 + c, inner && (r === 0 || r === 6 || c === 0 || c === 6 || (r >= 2 && r <= 4 && c >= 2 && c <= 4)));
      }
    };
    finder(0, 0); finder(0, N - 7); finder(N - 7, 0);
    for (let i = 8; i < N - 8; i++) { set(6, i, i % 2 === 0); set(i, 6, i % 2 === 0); }
    const al = ALIGN[v];
    for (const r of al) for (const c of al) {
      if ((r === 6 && c === 6) || (r === 6 && c === N - 7) || (r === N - 7 && c === 6)) continue;
      for (let dr = -2; dr <= 2; dr++) for (let dc = -2; dc <= 2; dc++) set(r + dr, c + dc, Math.max(Math.abs(dr), Math.abs(dc)) !== 1);
    }
    // Format info areas (filled per mask later) and the dark module
    for (let i = 0; i <= 8; i++) { if (i !== 6) { set(8, i, 0); set(i, 8, 0); } }
    for (let i = 0; i < 8; i++) { set(8, N - 1 - i, 0); set(N - 1 - i, 8, 0); }
    set(N - 8, 8, 1);
    if (v >= 7) {
      let rem = v;
      for (let i = 0; i < 12; i++) rem = (rem << 1) ^ ((rem >>> 11) * 0x1f25);
      const bits = (v << 12) | rem;
      for (let i = 0; i < 18; i++) {
        const bit = (bits >>> i) & 1, a = N - 11 + (i % 3), b = Math.floor(i / 3);
        set(a, b, bit); set(b, a, bit);
      }
    }
    return { N, m, fn };
  }

  function drawFormat(m, N, mask) {
    const data = mask;                      // level M = 00, then the 3 mask bits
    let rem = data;
    for (let i = 0; i < 10; i++) rem = (rem << 1) ^ ((rem >>> 9) * 0x537);
    const bits = ((data << 10) | rem) ^ 0x5412;
    const bit = (i) => (bits >>> i) & 1;
    // m[row][col]. First copy: bits 0-7 down column 8 (skipping the timing row), bits 8-14 along row 8 leftwards.
    for (let i = 0; i <= 5; i++) m[i][8] = bit(i);
    m[7][8] = bit(6); m[8][8] = bit(7); m[8][7] = bit(8);
    for (let i = 9; i < 15; i++) m[8][14 - i] = bit(i);
    // Second copy: bits 0-7 along row 8 from the right edge inwards, bits 8-14 down column 8 above the dark module.
    for (let i = 0; i < 8; i++) m[8][N - 1 - i] = bit(i);
    for (let i = 8; i < 15; i++) m[N - 15 + i][8] = bit(i);
    m[N - 8][8] = 1;
  }

  function placeData(sk, cw, mask) {
    const { N, fn } = sk;
    const m = sk.m.map(row => Uint8Array.from(row));
    const total = cw.length * 8;
    const f = MASKS[mask];
    let bi = 0;
    for (let col = N - 1, up = true; col > 0; col -= 2, up = !up) {
      if (col === 6) col--;
      for (let k = 0; k < N; k++) {
        const r = up ? N - 1 - k : k;
        for (const c of [col, col - 1]) {
          if (fn[r][c]) continue;
          const bit = bi < total ? (cw[bi >> 3] >> (7 - (bi & 7))) & 1 : 0;
          bi++;
          m[r][c] = bit ^ (f(r, c) ? 1 : 0);
        }
      }
    }
    drawFormat(m, N, mask);
    return m;
  }

  function penalty(m, N) {
    let p = 0;
    const scan = (get) => {
      for (let i = 0; i < N; i++) {
        let run = 0, prev = -1, s = '';
        for (let j = 0; j < N; j++) {
          const v = get(i, j); s += v;
          if (v === prev) { run++; if (run === 5) p += 3; else if (run > 5) p++; } else { prev = v; run = 1; }
        }
        for (const pat of ['10111010000', '00001011101']) for (let k = s.indexOf(pat); k >= 0; k = s.indexOf(pat, k + 1)) p += 40;
      }
    };
    scan((i, j) => m[i][j]); scan((i, j) => m[j][i]);
    for (let r = 0; r < N - 1; r++) for (let c = 0; c < N - 1; c++) {
      const v = m[r][c];
      if (v === m[r][c + 1] && v === m[r + 1][c] && v === m[r + 1][c + 1]) p += 3;
    }
    let dark = 0;
    for (const row of m) for (const v of row) dark += v;
    p += 10 * Math.floor(Math.abs(dark * 100 / (N * N) - 50) / 5);
    return p;
  }

  function encode(text) {
    const data = toBytes(text);
    const version = chooseVersion(data.length);
    const cw = codewords(data, version);
    const sk = skeleton(version);
    let best = null, bestScore = Infinity, bestMask = 0;
    for (let mask = 0; mask < 8; mask++) {
      const m = placeData(sk, cw, mask);
      const s = penalty(m, sk.N);
      if (s < bestScore) { best = m; bestScore = s; bestMask = mask; }
    }
    return { version, size: sk.N, mask: bestMask, codewords: cw, get: (r, c) => best[r][c] === 1 };
  }

  function svg(text, opts = {}) {
    const { size = 200, margin = 4, dark = '#000', light = '#fff' } = opts;
    const q = encode(text), N = q.size, total = N + 2 * margin;
    let d = '';
    for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) if (q.get(r, c)) d += `M${c + margin} ${r + margin}h1v1h-1z`;
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${total} ${total}" width="${size}" height="${size}" shape-rendering="crispEdges" role="img" aria-label="QR code"><rect width="${total}" height="${total}" fill="${light}"/><path d="${d}" fill="${dark}"/></svg>`;
  }

  const api = { encode, svg, rsEncode, MASKS };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  root.qrcode = api;
})(typeof window !== 'undefined' ? window : globalThis);
